
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_bhandh_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_bhandh", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.142736347313314e+00, -2.100521901746880e+00, -2.041345853955149e+00, -1.959322786405103e+00, -1.847450580375310e+00, -1.698332386364974e+00, -1.505925307115353e+00, -1.268730754046436e+00, -9.943948139552119e-01, -7.055419776173272e-01, -4.570964169292527e-01, -3.655069769674702e-01, -3.274079265379167e-01, -2.638010404844507e-01, -1.782526842024311e-01, -9.272348775310763e-02, -3.560783185883531e-02, -1.467800415162344e-02, -3.070623182981109e-03, -3.388338807853332e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


